<?php endif ?>
<details <?= !$sourceDetails||$sourceSearch!==''||$needsPayment?'open':'' ?>><summary><?= $needsPayment?$donationText('Zahlung dieses Belegs auswählen'):($sourceDetails?$donationText('Andere Zuwendung auswählen'):($formKind==='goods'?$donationText('Vorhandene Sachspende suchen'):$donationText('Vorhandene Geldspende oder Beitragszahlung suchen'))) ?></summary>
