<label for="donation-source-search"><?= $formKind==='goods'?$donationText('Sachspende, Gegenstand oder Spender suchen'):$donationText('Zahlung, Belegnummer oder Spender suchen') ?></label><div class="donation-source-input"><input class="form-control" id="donation-source-search" name="source_q" type="search" maxlength="150" value="<?= e($sourceSearch) ?>" autocomplete="off" placeholder="<?= $df('Namen oder Bezeichnung eingeben') ?>"><button class="btn btn-outline theme-secondary secondary" name="action" value="donation-search" formnovalidate><?= $df('Suchen') ?></button></div>
